SECURITY_SCHEMAS = {
    "api_key": "api_key",
    "petstore_auth": "petstore_auth"
}

# Test for finding pet by ID
@pytest.mark.parametrize("pet_id, expected_status, expected_body", [
    (10, 200, {"id": 10, "name": "doggie", "photoUrls": ["example.com/photo1"], "category": {"id": 1, "name": "Dogs"}}),
    (-1, 400, None),
    (9999, 404, None),
])
def test_get_pet_by_id(api_client, valid_api_key, pet_id, expected_status, expected_body):
    """
    Test the GET /pet/{petId} endpoint with valid and invalid pet IDs.
    """
    # Build headers
    headers = {"Authorization": f"Bearer {valid_api_key}"}

    # Make the API call
    response = api_client.get(API_ENDPOINT.format(petId=pet_id), headers=headers)

    # Assert the response status
    assert response.status_code == expected_status

    # Assert the response body for successful operations
    if expected_status == 200:
        response_json = response.json()
        assert "id" in response_json and "name" in response_json
        assert response_json["id"] == expected_body["id"]
        assert response_json["name"] == expected_body["name"]

